package com.nthexperience.desktop;
import org.json.*;import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import java.nio.charset.StandardCharsets;
public class EightPimModelsTest {
    JSONObject event()throws Exception{return new JSONObject().put("id","event_1").put("title","Dentist").put("start",1800000000000L).put("end",1800003600000L).put("zone","America/New_York").put("allDay",false).put("location","Office").put("notes","");}
    @Test public void appointmentsUseExclusiveEndAndRejectBadTimes()throws Exception{JSONObject e=EightPimModels.clean(EightPimModels.EVENTS,event());assertTrue(EightPimModels.overlaps(e,e.getLong("end")-1,e.getLong("end")+1));assertFalse(EightPimModels.overlaps(e,e.getLong("end"),e.getLong("end")+1));for(JSONObject bad:new JSONObject[]{event().put("end",1800000000000L),event().put("zone","Made/Up"),event().put("start",-1),event().put("title"," ")})try{EightPimModels.clean(EightPimModels.EVENTS,bad);fail();}catch(JSONException expected){}}
    @Test public void icsEscapesPropertiesAndFoldsUtf8WithoutBreakingCharacters()throws Exception{String notes="line one\r\nSUMMARY:injected,semicolon;\\"+String.join("",Collections.nCopies(60,"é"));String data=EightPimModels.ics(event().put("notes",notes).put("title","Visit, check;up"));assertTrue(data.startsWith("BEGIN:VCALENDAR\r\n"));assertFalse(data.contains("\r\nSUMMARY:injected"));for(String line:data.split("\r\n"))assertTrue(line.getBytes(StandardCharsets.UTF_8).length<=75);String unfolded=data.replace("\r\n ","");assertTrue(unfolded.contains("DESCRIPTION:line one\\nSUMMARY:injected\\,semicolon\\;\\\\"));assertTrue(unfolded.contains("SUMMARY:Visit\\, check\\;up"));assertTrue(unfolded.contains("DTSTART:"));}
    @Test public void allDayIcsRetainsLocalDatesAcrossDaylightSaving()throws Exception{Calendar start=Calendar.getInstance(TimeZone.getTimeZone("America/New_York"));start.clear();start.set(2027,Calendar.MARCH,14);Calendar end=(Calendar)start.clone();end.add(Calendar.DAY_OF_MONTH,1);assertEquals(23*3600000L,end.getTimeInMillis()-start.getTimeInMillis());String data=EightPimModels.ics(event().put("start",start.getTimeInMillis()).put("end",end.getTimeInMillis()).put("allDay",true));assertTrue(data.contains("DTSTART;VALUE=DATE:20270314\r\n"));assertTrue(data.contains("DTEND;VALUE=DATE:20270315\r\n"));}
    @Test public void mailValidatesRecipientsAndCannotInjectHeaders()throws Exception{JSONObject d=new JSONObject().put("to","one@example.com;two@example.com").put("subject","A&B?").put("body","Hello\nLine 2");String uri=EightPimModels.mailto(d);assertTrue(uri.startsWith("mailto:one@example.com,two@example.com?"));assertTrue(uri.contains("subject=A%26B%3F"));assertTrue(uri.contains("body=Hello%0ALine%202"));for(String to:new String[]{"", "bad", "x@example.com\r\nBcc: other@example.com"})try{EightPimModels.mailto(d.put("to",to));fail();}catch(JSONException expected){}}
    @Test public void attachmentsAreContentOnlyAndDeduplicated()throws Exception{JSONObject draft=new JSONObject().put("id","draft1").put("attachments",new JSONArray().put("content://docs/a").put("content://docs/a"));assertEquals(1,EightPimModels.clean(EightPimModels.DRAFTS,draft).getJSONArray("attachments").length());try{EightPimModels.clean(EightPimModels.DRAFTS,draft.put("attachments",new JSONArray().put("file:///private/key")));fail();}catch(JSONException expected){}}
    @Test public void mapBoundsAndCoordinatesRemainFiniteAndLocaleIndependent(){assertArrayEquals(new double[]{40.5,-74.2},EightPimModels.coordinates("40.5, -74.2"),.00001);for(String value:new String[]{"NaN,0","0,Infinity","86,0","0,181","40,20,10","geo:40,20"})assertNull(value,EightPimModels.coordinates(value));Locale before=Locale.getDefault();try{Locale.setDefault(Locale.GERMANY);String url=EightPimModels.mapUrl(40.5,-74.2,12);assertTrue(url.startsWith("https://www.openstreetmap.org/export/embed.html?"));assertTrue(url.contains("40.5000000%2C-74.2000000"));}finally{Locale.setDefault(before);}}
    @Test public void portableRecordsAreBoundedAndCannotDuplicateIdentifiers()throws Exception{JSONObject p=new JSONObject().put("id","contact1").put("name","Person").put("device",42);JSONObject clean=EightPimModels.clean(EightPimModels.PEOPLE,p);assertFalse(clean.has("device"));try{EightPimModels.clean(EightPimModels.PEOPLE,new JSONArray().put(p).put(p));fail();}catch(JSONException expected){}try{EightPimModels.clean(EightPimModels.PEOPLE,p.put("email","a@b.com\nBcc: x@y.com"));fail();}catch(JSONException expected){}}
    @Test public void savedPlacesRejectInvalidCoordinatesAndRoundTrip()throws Exception{JSONObject p=new JSONObject().put("id","place1").put("name","Home").put("lat",40.5).put("lon",-74.2).put("notes","A place");assertEquals(40.5,EightPimModels.clean(EightPimModels.PLACES,p).getDouble("lat"),0);try{EightPimModels.clean(EightPimModels.PLACES,p.put("lon",181));fail();}catch(JSONException expected){}}
}
